const raw = $input.first().json;
const body = raw.body || raw;

const score   = ((body.fraud_score || 0) * 100).toFixed(1);
const sev     = (body.severity || 'low').toLowerCase();
const reasons = Array.isArray(body.reasons)
  ? body.reasons.join(' | ')
  : (body.reasons || 'N/A');

// Routing logic
let channel = 'log_only';
let action  = 'LOGGED';
if (sev === 'high' || sev === 'critical') {
  channel = 'high_alert';
  action  = 'BLOCKED & ESCALATED';
  // TODO: aquí puedes agregar Email / Slack / PagerDuty
  console.log('🚨 HIGH FRAUD ALERT | tx:', body.transaction_id,
    '| user:', body.user_id, '| score:', score + '%',
    '| reasons:', reasons);
} else if (sev === 'medium') {
  channel = 'review_queue';
  action  = 'QUEUED FOR REVIEW';
  // TODO: aquí puedes agregar ticket Jira / email de revisión
  console.log('⚠️  MEDIUM RISK REVIEW | tx:', body.transaction_id,
    '| score:', score + '%');
} else {
  console.log('ℹ️  LOW RISK | tx:', body.transaction_id, '| score:', score + '%');
}

const emoji = { high:'🚨', critical:'🚨', medium:'⚠️', low:'ℹ️' }[sev] || 'ℹ️';

return [{ json: {
  ...body,
  processed_at: new Date().toISOString(),
  score_pct:    score,
  severity_fmt: sev.toUpperCase(),
  emoji:        emoji,
  reasons_str:  reasons,
  channel:      channel,
  action:       action,
  summary:      emoji + ' [' + sev.toUpperCase() + '] '
                + 'tx:' + body.transaction_id
                + ' | user:' + body.user_id
                + ' | score:' + score + '%'
                + ' | ' + action
                + ' | ' + reasons
} }];
